import React, { useState } from 'react';
import { motion } from 'framer-motion';

const Contact = () => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    subject: 'General Inquiry',
    message: ''
  });

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log('Form submitted:', formData);
    // Handle form submission here
  };

  const contactInfo = [
    {
      icon: 'fas fa-envelope',
      title: 'Email',
      value: 'simon.doe@example.com',
      href: 'mailto:simon.doe@example.com'
    },
    {
      icon: 'fas fa-phone-alt',
      title: 'Phone',
      value: '+1 (234) 567-890',
      href: 'tel:+1234567890'
    },
    {
      icon: 'fas fa-map-marker-alt',
      title: 'Location',
      value: 'San Francisco, CA',
      href: null
    }
  ];

  const socialLinks = [
    { icon: 'fab fa-twitter', href: '#' },
    { icon: 'fab fa-linkedin-in', href: '#' },
    { icon: 'fab fa-github', href: '#' },
    { icon: 'fab fa-dribbble', href: '#' }
  ];

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.1
      }
    }
  };

  const itemVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: {
      opacity: 1,
      y: 0,
      transition: {
        duration: 0.5
      }
    }
  };
  return (
    <motion.section
      initial="hidden"
      whileInView="visible"
      viewport={{ once: true, amount: 0.1 }}
      variants={containerVariants}
      className="mb-12"
    >
      <motion.h1
        variants={itemVariants}
        className="text-4xl md:text-5xl font-black text-gray-900 dark:text-white mb-6"
      >
        Contact Me
      </motion.h1>
      <motion.p
        variants={itemVariants}
        className="text-lg leading-relaxed mb-10 text-gray-600 dark:text-gray-300 max-w-3xl"
      >
        Interested in working together? Fill out the form below with some info about your project and I will get back to you as soon as I can. Please allow a couple of days for me to respond.
      </motion.p>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
        <motion.div variants={itemVariants} className="lg:col-span-2">
          <motion.form
            onSubmit={handleSubmit}
            className="space-y-6"
            initial="hidden"
            animate="visible"
            variants={containerVariants}
          >
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <motion.div variants={itemVariants}>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2" htmlFor="name">
                  Name
                </label>
                <motion.input
                  whileFocus={{ scale: 1.02 }}
                  className="w-full px-4 py-3 rounded-md border border-gray-300 dark:border-gray-600 bg-white dark:bg-surface-dark text-gray-900 dark:text-white focus:ring-primary focus:border-primary transition-colors"
                  id="name"
                  name="name"
                  placeholder="Your Name"
                  required
                  type="text"
                  value={formData.name}
                  onChange={handleChange}
                />
              </motion.div>
              <motion.div variants={itemVariants}>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2" htmlFor="email">
                  Email
                </label>
                <motion.input
                  whileFocus={{ scale: 1.02 }}
                  className="w-full px-4 py-3 rounded-md border border-gray-300 dark:border-gray-600 bg-white dark:bg-surface-dark text-gray-900 dark:text-white focus:ring-primary focus:border-primary transition-colors"
                  id="email"
                  name="email"
                  placeholder="email@example.com"
                  required
                  type="email"
                  value={formData.email}
                  onChange={handleChange}
                />
              </motion.div>
            </div>
            <motion.div variants={itemVariants}>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2" htmlFor="subject">
                Subject
              </label>
              <motion.select
                whileFocus={{ scale: 1.02 }}
                className="w-full px-4 py-3 rounded-md border border-gray-300 dark:border-gray-600 bg-white dark:bg-surface-dark text-gray-900 dark:text-white focus:ring-primary focus:border-primary transition-colors"
                id="subject"
                name="subject"
                value={formData.subject}
                onChange={handleChange}
              >
                <option>General Inquiry</option>
                <option>Project Proposal</option>
                <option>Freelance Opportunity</option>
                <option>Other</option>
              </motion.select>
            </motion.div>
            <motion.div variants={itemVariants}>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2" htmlFor="message">
                Message
              </label>
              <motion.textarea
                whileFocus={{ scale: 1.02 }}
                className="w-full px-4 py-3 rounded-md border border-gray-300 dark:border-gray-600 bg-white dark:bg-surface-dark text-gray-900 dark:text-white focus:ring-primary focus:border-primary transition-colors h-40 resize-y"
                id="message"
                name="message"
                placeholder="Your message here..."
                required
                value={formData.message}
                onChange={handleChange}
              />
            </motion.div>
            <motion.button
              variants={itemVariants}
              whileHover={{ scale: 1.05, y: -2 }}
              whileTap={{ scale: 0.95 }}
              className="bg-primary hover:bg-primary-dark text-white font-bold py-3 px-8 rounded shadow-md transition-transform transform hover:-translate-y-0.5 flex items-center justify-center w-full md:w-auto"
              type="submit"
            >
              <i className="fas fa-paper-plane mr-2"></i> Send Message
            </motion.button>
          </motion.form>
        </motion.div>
        <motion.div variants={itemVariants} className="lg:col-span-1 space-y-8">
          <motion.div
            whileHover={{ y: -2 }}
            className="bg-surface-light dark:bg-surface-dark p-6 rounded-lg border border-gray-200 dark:border-gray-700 shadow-sm"
          >
            <h3 className="text-xl font-bold text-gray-900 dark:text-white mb-4">Contact Info</h3>
            <ul className="space-y-4">
              {contactInfo.map((info, index) => (
                <motion.li
                  key={index}
                  whileHover={{ x: 5 }}
                  className="flex items-start"
                >
                  <div className="shrink-0 bg-primary/10 p-2 rounded text-primary mt-1">
                    <i className={info.icon}></i>
                  </div>
                  <div className="ml-4">
                    <h4 className="text-sm font-bold text-gray-900 dark:text-white">{info.title}</h4>
                    {info.href ? (
                      <motion.a
                        whileHover={{ color: '#54B689' }}
                        className="text-gray-600 dark:text-gray-400 hover:text-primary dark:hover:text-primary transition-colors"
                        href={info.href}
                      >
                        {info.value}
                      </motion.a>
                    ) : (
                      <span className="text-gray-600 dark:text-gray-400">{info.value}</span>
                    )}
                  </div>
                </motion.li>
              ))}
            </ul>
          </motion.div>

          <motion.div
            whileHover={{ y: -2 }}
            className="bg-surface-light dark:bg-surface-dark p-6 rounded-lg border border-gray-200 dark:border-gray-700 shadow-sm"
          >
            <h3 className="text-xl font-bold text-gray-900 dark:text-white mb-4">Follow Me</h3>
            <div className="flex space-x-4">
              {socialLinks.map((link, index) => (
                <motion.a
                  key={index}
                  whileHover={{ scale: 1.1, backgroundColor: '#54B689', color: '#ffffff' }}
                  whileTap={{ scale: 0.95 }}
                  className="w-10 h-10 rounded-full bg-gray-200 dark:bg-gray-700 flex items-center justify-center text-gray-600 dark:text-gray-300 hover:bg-primary hover:text-white dark:hover:bg-primary dark:hover:text-white transition-colors"
                  href={link.href}
                >
                  <i className={link.icon}></i>
                </motion.a>
              ))}
            </div>
          </motion.div>
        </motion.div>
      </div>
    </motion.section>
  );
};

export default Contact;
